class Solution {
    bool leaf(TreeNode* node) {
        return node && !node->left && !node->right;
    }

    void collectLeaves(TreeNode* node, vector<int>& result) {
        if (!node) {
            return;
        }
        if (leaf(node)) {
            result.push_back(node->val);
            return;
        }
        collectLeaves(node->left, result);
        collectLeaves(node->right, result);
    }

public:
    vector<int> boundaryOfBinaryTree(TreeNode* root) {
        if (!root) {
            return {};
        }
        if (leaf(root)) {
            return {root->val};
        }
        vector<int> result{root->val};
        for (TreeNode* node = root->left; node && !leaf(node);
             node = node->left ? node->left : node->right) {
            result.push_back(node->val);
        }
        collectLeaves(root->left, result);
        collectLeaves(root->right, result);
        vector<int> right;
        for (TreeNode* node = root->right; node && !leaf(node);
             node = node->right ? node->right : node->left) {
            right.push_back(node->val);
        }
        result.insert(result.end(), right.rbegin(), right.rend());
        return result;
    }
};
